package me.vertex.core.trade;
import me.vertex.core.lang.Messages; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.inventory.InventoryClickEvent;
/** Prevents history entries from being taken and delegates paged navigation. */
public final class TradeHistoryListener implements Listener { private final TradeManager manager; private final Messages messages; public TradeHistoryListener(TradeManager manager,Messages messages){this.manager=manager;this.messages=messages;} @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!(e.getView().getTopInventory().getHolder() instanceof TradeHistoryMenu.Holder h))return;e.setCancelled(true);String label=h.filter()==null?"all trades":org.bukkit.Bukkit.getOfflinePlayer(h.filter()).getName();if(e.getRawSlot()==45&&h.page()>0)manager.openHistory(p,h.filter(),label,h.page()-1);else if(e.getRawSlot()==53)manager.openHistory(p,h.filter(),label,h.page()+1);} }
